-static const iree_hal_semaphore_vtable_t iree_hal_rocm_semaphore_vtable;
-
-static iree_hal_rocm_semaphore_t* iree_hal_rocm_semaphore_cast(
-    iree_hal_semaphore_t* base_value) {
