-      context->host_allocator, sizeof(*semaphore), (void**)&semaphore);
-  if (iree_status_is_ok(status)) {
-    iree_hal_semaphore_initialize(&iree_hal_rocm_semaphore_vtable,
-                                  &semaphore->base);
